export function CaseStudyCard({
  company = "{{company}}",
  result = "{{result}}",
  summary = "{{summary}}",
  accent = "{{accent}}",
  showLink = {{showLink}},
}) {
  return (
    <article style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", maxWidth: 300, padding: 20,
      border: "1px solid #24143022", borderRadius: 14, background: "#FAF7F2" }}>
      <p style={{ margin: "0 0 8px", fontSize: 12, fontWeight: 700, textTransform: "uppercase", letterSpacing: "0.05em", color: "#24143088" }}>{company}</p>
      <p style={{ margin: "0 0 10px", fontSize: 26, fontWeight: 800, color: accent }}>{result}</p>
      <p style={{ margin: "0 0 14px", fontSize: 14, color: "#241430cc" }}>{summary}</p>
      {showLink && <a href="#" style={{ color: accent, textDecoration: "none", fontWeight: 600, fontSize: 14 }}>Read case study &rarr;</a>}
    </article>
  );
}
